[SysClientCacheDataMethodAttribute(true)]
display RealBase durationMin()
{
    RealBase res;
    ;
    if (this.LastEndTime && this.LastBeginTime)
    {
        res = any2real(DateTimeUtil::getDifference(this.LastEndTime, this.LastBeginTime) / 60);
    }

    return res;
}

/// <summary>
/// Cutoff date and time of the task: records up to and including it are deleted.
/// </summary>
/// <returns>The cutoff date and time.</returns>
TransDateTime getCleanupDateTime()
{
    return DEV_CleanupTaskSettings::calcCleanupDateTime(this.CleanupDateType, this.CleanupDays, this.CleanupDate);
}

/// <summary>
/// The one rule for the cutoff of all tasks: the end of the cutoff day in the user's time zone.
/// Records up to and including the cutoff are deleted.
/// </summary>
/// <param name = "_cleanupDateType">Periodic: keep the last _cleanupDays days. To date: delete up to and including _cleanupDate.</param>
/// <param name = "_cleanupDays">The number of days to keep, for Periodic.</param>
/// <param name = "_cleanupDate">The last date to delete, for To date.</param>
/// <returns>The cutoff date and time.</returns>
public static TransDateTime calcCleanupDateTime(DEV_CleanupDateType _cleanupDateType, Days _cleanupDays, TransDate _cleanupDate)
{
    TimeZone    timeZone = DateTimeUtil::getUserPreferredTimeZone();
    TransDate   cleanupDate;

    switch (_cleanupDateType)
    {
        case DEV_CleanupDateType::Periodic:
            cleanupDate = DateTimeUtil::getToday(timeZone) - _cleanupDays;
            break;

        case DEV_CleanupDateType::ToDate:
            cleanupDate = _cleanupDate;
            break;
    }

    if (!cleanupDate)
    {
        throw error("Cleanup date is not specified.");
    }

    return datetoendUtcDateTime(cleanupDate, timeZone);
}

public static DEV_CleanupTaskSettings find(DEV_CleanUpTaskName _cleanupTaskName,
                                           boolean             _forUpdate = false)
{
    DEV_CleanupTaskSettings DEV_CleanupTaskSettings;

    if (_cleanupTaskName)
    {
        DEV_CleanupTaskSettings.selectForUpdate(_forUpdate);

        select firstonly DEV_CleanupTaskSettings
            where DEV_CleanupTaskSettings.CleanupTaskName == _cleanupTaskName;
    }

    return DEV_CleanupTaskSettings;
}

/// <summary>
/// The task class of these settings; null when the class does not exist.
/// </summary>
public DEV_CleanupDataTaskBase cleanupTask()
{
    DEV_CleanupDataTaskBase     cleanupTask;
    ClassId                     classId = className2Id(this.ClassName);

    if (classId)
    {
        cleanupTask = new DictClass(classId).makeObject();
        cleanupTask.parmCleanupTaskSettings(this);
    }

    return cleanupTask;
}

/// <summary>
/// The number of days to keep, for standard cleanup classes that take days instead of a date.
/// </summary>
/// <param name = "_company">The company; used with By company.</param>
/// <returns>The number of days from today to the cutoff date.</returns>
public Days cleanupDaysForCompany(DataAreaId _company = curExt())
{
    TimeZone        timeZone        = DateTimeUtil::getUserPreferredTimeZone();
    utcdatetime     cleanupDateTime = this.cleanupDateTimeForCompany(_company);

    return DateTimeUtil::getToday(timeZone) - DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(cleanupDateTime, timeZone));
}

/// <summary>
/// Cutoff date and time for a company: from the By company settings when they are used; otherwise, of the task.
/// </summary>
/// <param name = "_company">The company.</param>
/// <returns>The cutoff date and time.</returns>
public utcdatetime cleanupDateTimeForCompany(DataAreaId _company = curExt())
{
    DEV_CleanupTaskSettingsCompany  line;

    if (this.PerCompanySetup)
    {
        line = this.getCleanupSettingsForCompany(_company);

        return DEV_CleanupTaskSettings::calcCleanupDateTime(line.CleanupDateType, line.CleanupDays, line.CleanupDate);
    }

    return this.getCleanupDateTime();
}

public boolean isCleanupAllowedForCompany(DataAreaId _company = curExt())
{
    boolean ret;

    if (!this.PerCompanySetup)
    {
        ret = true;
    }
    else if (DEV_CleanupTaskSettingsCompany::find(this.RecId, _company)
        || DEV_CleanupTaskSettingsCompany::find(this.RecId, ''))
    {
        ret = true;
    }

    return ret;
}

public DEV_CleanupTaskSettingsCompany getCleanupSettingsForCompany(DataAreaId _company = curExt())
{
    DEV_CleanupTaskSettingsCompany ret;

    ret = DEV_CleanupTaskSettingsCompany::find(this.RecId, _company);
    if (!ret)
    {
        ret = DEV_CleanupTaskSettingsCompany::find(this.RecId, '');
    }
    if (! ret)
    {
        throw error(strFmt("Task %1. Setting for company %2 doesn't exist",
            this.CleanupTaskName, _company));
    }


    return ret;
}

[SysClientCacheDataMethodAttribute(true)]
public display DEV_CleanupSettingsDesc perCompanySettings()
{
    #define.all('All')
    #define.comma(', ')
    str                             ret;
    DEV_CleanupTaskSettingsCompany     line;

    if (this.PerCompanySetup)
    {
        while select line
            order by CleanupDataArea
            where   line.CleanupTaskSettingsRecId == this.RecId
        {
            if (ret)
            {
                ret += #comma;
            }
            if (line.CleanupDataArea)
            {
                ret += line.CleanupDataArea;
            }
            else
            {
                ret += #all;
            }

            ret += strFmt(": %1", line.CleanupDays);
        }            
    }

    return ret;
}
